select case when amount >= 4500 then 'high' when amount >= 900 then 'mid' else 'low' end as amount_bucket, case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end as txn_cohort, avg(amount) as avg_amount, count(case when merchant = 'Shell' then 1 end) as shell_count, count(*) as total_count from transactions group by case when amount >= 4500 then 'high' when amount >= 900 then 'mid' else 'low' end, case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end order by avg_amount desc, amount_bucket asc
